class Colliding:
    def __init__(self, value):
        self.value = value

    def __hash__(self):
        return 42

    def __eq__(self, other):
        return isinstance(other, Colliding) and self.value == other.value

    def __repr__(self):
        return f"Colliding({self.value!r})"

