# simulate two distinct dict keys mapping to same (name, depth): impossible in one dict,
# so use a mapping class preserving duplicate iteration order
class DupMapping:
    def __init__(self, items):
        self._items = items
    def get(self, key, default=None):
        for k, v in self._items:
            if k == key:
                return v
        return default
    def items(self):
        return iter(self._items)
mapping = DupMapping([("l_1_foo", "first"), ("l_1_foo", "second"), ("l_2_bar", "b")])

